static void fill_test_matrix(std::vector<double>& data, std::size_t M, std::size_t N, int seed = 42) {
  std::mt19937 gen(seed);
  std::normal_distribution<double> dist(100.0, 50.0);
  for (auto& val : data) {
    val = dist(gen);
  }
}

static void verify_standardized(const std::vector<double>& data, std::size_t M, std::size_t N, double tol = 1e-6) {
  for (std::size_t j = 0; j < N; ++j) {
    double sum = 0.0, sq_sum = 0.0;
    for (std::size_t i = 0; i < M; ++i) {
      double x = data[j * M + i];
      sum += x;
      sq_sum += x * x;
    }
    double mean = sum / M;
    double var = (sq_sum - sum * sum / M) / (M - 1);
    double stddev = std::sqrt(var);

    ASSERT_NEAR(mean, 0.0, tol);
    ASSERT_NEAR(stddev, 1.0, tol);
  }
}

TEST(StandardFitTransformCpu, ThrowsOnSizeMismatch) {
  std::vector<double> data(100, 1.1);
  const std::size_t M = 20, N = 4;

  ASSERT_THAT(
    [&](){normalize::standard::fit_transform_cpu(data, M, N); },
    testing::ThrowsMessage<std::invalid_argument>("standard::fit_transform_cpu - data size does not equal M * N")
  );
}

